// Carrier product codes are generated by the backend as DYSKA-TIP-<minor units>, DYSKA-PROTECTION,
// DYSKA-PRIORITY and DYSKA-CARD (see the backend README, "Nosne produkty").
export const CODE_PREFIX = "DYSKA-";
export const TIP_CODE_PREFIX = "DYSKA-TIP-";
export const PROTECTION_CODE = "DYSKA-PROTECTION";
export const PRIORITY_CODE = "DYSKA-PRIORITY";
export const DEFAULT_CARD_CODE = "DYSKA-CARD";
// Whitelist for codes that arrive from the backend; anything else is dropped (the block stays hidden for it).
export const CARRIER_CODE_RE = /^DYSKA-(TIP-\d{1,7}|PROTECTION|PRIORITY|CARD)$/;
export const TIP_CODE_RE = /^DYSKA-TIP-(\d{1,7})$/;

export const ROOT_ATTR = "data-dyska";
export const BLOCK_ATTR = "data-dyska-root";
export const STYLE_ATTR = "data-dyska-style";

export const FETCH_TIMEOUT_MS = 8000;
export const CART_WAIT_TIMEOUT_MS = 8000;
export const CART_POLL_MS = 120;
export const NOTES_DEBOUNCE_MS = 700;
export const CONFIG_RETRY_MS = 30000;
// Retry delays for the notes sync: 429 without a Retry-After header, and the cap for a Retry-After value.
export const RETRY_DEFAULT_MS = 30000;
export const RETRY_MAX_MS = 120000;
// After this many 429 answers with reason "capacity" in a row nothing more is sent until the page is loaded again.
export const MAX_CAPACITY_ATTEMPTS = 3;
// How often a foreign script may replace the checkout hook before we stop wrapping it again.
export const MAX_HOOK_WRAPS = 3;

// Backend limit is 10 notes per ref (MAX_NOTES_PER_REF).
export const MAX_CARDS = 10;
export const REF_RE = /^[A-Za-z0-9_-]{22}$/;
export const ESHOP_ID_RE = /^\d{1,12}$/;

export const STORAGE_KEY = "dyska:gift";

export const CART_EVENTS = ["ShoptetDOMContentLoaded", "ShoptetDOMCartContentLoaded", "ShoptetDataLayerUpdated"];

export const REMARK_SELECTOR = "textarea#remark";
export const ADD_NOTE_SELECTOR = "#add-note";

// Where the block is inserted on the cart page, first match wins. A merchant can force the position
// with <div id="dyska-mount"></div>. Selectors other than #dyska-mount are unverified (see README, TODO).
export const MOUNT_TARGETS = [
  { selector: "#dyska-mount", position: "append" },
  { selector: ".cart-content .cart-table", position: "after" },
  { selector: ".cart-table", position: "after" },
  { selector: ".cart-content", position: "append" },
  { selector: "#content-wrapper", position: "append" },
  { selector: "main", position: "append" },
];
